// Uses cleanup commands generated by WorldTraining.clear_tile_items.
const fs=require('fs'),mineflayer=require('mineflayer'),input=JSON.parse(fs.readFileSync('logs/reset-item-fixture.json','utf8')),token=fs.readFileSync('data/api-token','utf8').trim(),wait=ms=>new Promise(r=>setTimeout(r,ms));
const b=mineflayer.createBot({host:'127.0.0.1',port:25565,username:'LabResetCheck',version:'1.21.4'}),messages=[];b.on('messagestr',s=>messages.push(s));
async function admin(data){for(let i=0;i<10;i++){const r=await fetch('http://127.0.0.1:8000/admin/action',{method:'POST',headers:{'X-Lab-Token':token,'Content-Type':'application/json'},body:JSON.stringify({...data,player:b.username})});if(r.ok)return;const error=await r.text();if(!error.includes('not online'))throw Error(error);await wait(500);}throw Error('Fixture player not listed');}
async function cmd(c){b.chat('/'+c);await wait(150);}
async function count(){const at=messages.length;await cmd('execute store result score #reset_items lab_world if entity @e[tag=lab_reset_probe]');await cmd('scoreboard players get #reset_items lab_world');await wait(150);const match=messages.slice(at).join('\n').match(/#reset_items has (\d+)/);if(!match)throw Error('Missing entity-count acknowledgement: '+messages.slice(at).join(' '));return Number(match[1]);}
b.once('spawn',async()=>{const j=input.job,result={fixture:'Embedded item at Y40, high item at Y240, template-tile item and an adjacent-tile control; no block changes.'};try{
 await wait(1500);await admin({action:'gamemode',gamemode:'spectator'});await admin({action:'op'});await wait(1000);await admin({action:'teleport-coordinates',x:j.dest+8,y:190,z:j.z+8});
 for(const x of [j.dest,j.source])await cmd(`forceload add ${x} ${j.z} ${x+j.width-1} ${j.z+15}`);await wait(1000);
 for(const [x,y,z] of [[j.dest+2,40,j.z+2],[j.dest+3,240,j.z+3],[j.source+2,40,j.z+2],[j.dest+j.width+3,190,j.z+3]])await cmd(`summon item ${x+.5} ${y} ${z+.5} {Tags:["lab_reset_probe"],NoGravity:1b,Item:{id:"minecraft:cobblestone",count:1}}`);
 result.before=await count();for(const c of input.commands)await cmd(c);result.after=await count();result.success=result.before===4&&result.after===1;
 }catch(e){result.error=e.stack;}finally{
 await cmd('kill @e[tag=lab_reset_probe]');await cmd('scoreboard players reset #reset_items lab_world');for(const x of [j.dest,j.source])await cmd(`forceload remove ${x} ${j.z} ${x+j.width-1} ${j.z+15}`);await admin({action:'deop'}).catch(()=>{});fs.writeFileSync('docs/reset-items-native.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));b.quit();setTimeout(()=>process.exit(result.success?0:1),200);
 }});setTimeout(async()=>{await admin({action:'deop'}).catch(()=>{});b.quit();process.exit(1);},30000).unref();
